// 0010
define('MESSAGE_DISALLOWED', 0x4);
// 0100
define('MESSAGE_PERMITTED', 0x8);
// 1000
define('MESSAGE_FORCED', 0xc);
// 1100
define('MESSAGE_PERMITTED_MASK', 0xc);
